import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.DaGSOal_.js";const p=JSON.parse('{"title":"Usage Guide","description":"","frontmatter":{"sidebar_position":3},"headers":[],"relativePath":"asset-size-analyzer/usage.md","filePath":"asset-size-analyzer/usage.md","lastUpdated":1777104744000}'),l={name:"asset-size-analyzer/usage.md"};function o(r,e,n,h,c,d){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="usage-guide" tabindex="-1">Usage Guide <a class="header-anchor" href="#usage-guide" aria-label="Permalink to &quot;Usage Guide&quot;">​</a></h1><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><h3 id="step-1-open-asset-size-analyzer" tabindex="-1">Step 1: Open Asset Size Analyzer <a class="header-anchor" href="#step-1-open-asset-size-analyzer" aria-label="Permalink to &quot;Step 1: Open Asset Size Analyzer&quot;">​</a></h3><ol><li>Go to <strong>Window → Asset Size Analyzer</strong></li><li>A new window opens with the analyzer interface</li></ol><h3 id="step-2-scan-your-assets" tabindex="-1">Step 2: Scan Your Assets <a class="header-anchor" href="#step-2-scan-your-assets" aria-label="Permalink to &quot;Step 2: Scan Your Assets&quot;">​</a></h3><ol><li>Click <strong>&quot;Scan All Assets&quot;</strong> to analyze your entire project</li><li>Wait for the scan to complete (5-30 seconds for large projects)</li><li>Results appear in the sortable table</li></ol><p>That&#39;s it! You&#39;re ready to analyze.</p><h2 id="understanding-the-interface" tabindex="-1">Understanding the Interface <a class="header-anchor" href="#understanding-the-interface" aria-label="Permalink to &quot;Understanding the Interface&quot;">​</a></h2><h3 id="main-table-columns" tabindex="-1">Main Table Columns <a class="header-anchor" href="#main-table-columns" aria-label="Permalink to &quot;Main Table Columns&quot;">​</a></h3><ul><li><strong>Asset Name:</strong> The name of the asset</li><li><strong>Asset Type:</strong> Type (Texture, Mesh, Material, etc.)</li><li><strong>Disk Size:</strong> Actual file size on disk</li><li><strong>Memory Size:</strong> Estimated runtime memory usage</li><li><strong>Path:</strong> Full project path to the asset</li></ul><h3 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h3><p>Click any column header to sort by that column:</p><ul><li>Click once for ascending order</li><li>Click again for descending order</li><li>Visual indicator shows current sort</li></ul><h2 id="filtering-assets" tabindex="-1">Filtering Assets <a class="header-anchor" href="#filtering-assets" aria-label="Permalink to &quot;Filtering Assets&quot;">​</a></h2><h3 id="by-asset-type" tabindex="-1">By Asset Type <a class="header-anchor" href="#by-asset-type" aria-label="Permalink to &quot;By Asset Type&quot;">​</a></h3><p>Use the dropdown menu to filter by specific types:</p><ul><li>All Assets</li><li>Textures</li><li>Static Meshes</li><li>Materials</li><li>Sounds</li><li>And more...</li></ul><h3 id="by-size-threshold" tabindex="-1">By Size Threshold <a class="header-anchor" href="#by-size-threshold" aria-label="Permalink to &quot;By Size Threshold&quot;">​</a></h3><p>Set a minimum size to hide small assets:</p><ol><li>Enter size in MB in the threshold field</li><li>Only assets larger than threshold are shown</li><li>Perfect for finding the biggest offenders</li></ol><h3 id="by-search" tabindex="-1">By Search <a class="header-anchor" href="#by-search" aria-label="Permalink to &quot;By Search&quot;">​</a></h3><p>Use the search box to find specific assets by name or path.</p><h2 id="scanning-options" tabindex="-1">Scanning Options <a class="header-anchor" href="#scanning-options" aria-label="Permalink to &quot;Scanning Options&quot;">​</a></h2><h3 id="scan-all-assets" tabindex="-1">Scan All Assets <a class="header-anchor" href="#scan-all-assets" aria-label="Permalink to &quot;Scan All Assets&quot;">​</a></h3><p>Analyzes every asset in your Content folder:</p><ul><li>Most comprehensive analysis</li><li>Takes longer for large projects</li><li>Recommended for full project audits</li></ul><h3 id="scan-specific-folder" tabindex="-1">Scan Specific Folder <a class="header-anchor" href="#scan-specific-folder" aria-label="Permalink to &quot;Scan Specific Folder&quot;">​</a></h3><p>Right-click any folder in Content Browser:</p><ol><li>Select <strong>&quot;Analyze Folder Size&quot;</strong> (if available)</li><li>Or open analyzer and manually scan</li><li>Faster for targeted analysis</li></ol><h2 id="exporting-data" tabindex="-1">Exporting Data <a class="header-anchor" href="#exporting-data" aria-label="Permalink to &quot;Exporting Data&quot;">​</a></h2><h3 id="csv-export" tabindex="-1">CSV Export <a class="header-anchor" href="#csv-export" aria-label="Permalink to &quot;CSV Export&quot;">​</a></h3><ol><li>Click <strong>&quot;Export to CSV&quot;</strong> button</li><li>Choose save location in file picker</li><li>CSV file includes all visible assets with full information</li></ol><h3 id="what-s-included" tabindex="-1">What&#39;s Included <a class="header-anchor" href="#what-s-included" aria-label="Permalink to &quot;What&#39;s Included&quot;">​</a></h3><p>The CSV export contains:</p><ul><li>Asset Name</li><li>Asset Type</li><li>Disk Size (bytes)</li><li>Memory Size (bytes)</li><li>Full Asset Path</li></ul><p>Perfect for:</p><ul><li>Sharing with team</li><li>Creating reports</li><li>Tracking size over time</li><li>External analysis in Excel/Sheets</li></ul><h2 id="common-workflows" tabindex="-1">Common Workflows <a class="header-anchor" href="#common-workflows" aria-label="Permalink to &quot;Common Workflows&quot;">​</a></h2><h3 id="pre-shipping-optimization" tabindex="-1">Pre-Shipping Optimization <a class="header-anchor" href="#pre-shipping-optimization" aria-label="Permalink to &quot;Pre-Shipping Optimization&quot;">​</a></h3><p>Before releasing your game:</p><ol><li>Click <strong>&quot;Scan All Assets&quot;</strong></li><li>Sort by <strong>Disk Size</strong> (descending)</li><li>Review the largest assets</li><li>Identify optimization opportunities</li><li>Export report for documentation</li></ol><h3 id="memory-budget-tracking" tabindex="-1">Memory Budget Tracking <a class="header-anchor" href="#memory-budget-tracking" aria-label="Permalink to &quot;Memory Budget Tracking&quot;">​</a></h3><p>For performance optimization:</p><ol><li>Scan all assets</li><li>Sort by <strong>Memory Size</strong></li><li>Filter by asset type (e.g., Textures)</li><li>Identify assets exceeding your budget</li><li>Plan compression or LOD strategies</li></ol><h3 id="asset-audit" tabindex="-1">Asset Audit <a class="header-anchor" href="#asset-audit" aria-label="Permalink to &quot;Asset Audit&quot;">​</a></h3><p>For quality reviews:</p><ol><li>Scan project</li><li>Export to CSV</li><li>Share with team</li><li>Review unusual sizes</li><li>Plan cleanup or optimization</li></ol><h3 id="finding-specific-large-assets" tabindex="-1">Finding Specific Large Assets <a class="header-anchor" href="#finding-specific-large-assets" aria-label="Permalink to &quot;Finding Specific Large Assets&quot;">​</a></h3><p>Quick targeted search:</p><ol><li>Set size threshold (e.g., 10 MB)</li><li>Filter by asset type</li><li>Sort by size</li><li>Immediate results</li></ol><h2 id="tips-best-practices" tabindex="-1">Tips &amp; Best Practices <a class="header-anchor" href="#tips-best-practices" aria-label="Permalink to &quot;Tips &amp; Best Practices&quot;">​</a></h2><h3 id="performance-tips" tabindex="-1">Performance Tips <a class="header-anchor" href="#performance-tips" aria-label="Permalink to &quot;Performance Tips&quot;">​</a></h3><p>✅ <strong>Do:</strong></p><ul><li>Close other heavy Editor windows during scan</li><li>Use folder scans for quick checks</li><li>Filter by type for faster results</li></ul><h3 id="analysis-tips" tabindex="-1">Analysis Tips <a class="header-anchor" href="#analysis-tips" aria-label="Permalink to &quot;Analysis Tips&quot;">​</a></h3><p>✅ <strong>Do:</strong></p><ul><li>Export regular reports to track size over time</li><li>Focus on largest assets first (80/20 rule)</li><li>Check both disk and memory sizes</li><li>Share findings with team</li></ul><p>❌ <strong>Don&#39;t:</strong></p><ul><li>Don&#39;t scan during active builds</li><li>Don&#39;t ignore memory sizes (affects runtime)</li><li>Don&#39;t optimize everything - focus on impact</li></ul><h3 id="team-workflows" tabindex="-1">Team Workflows <a class="header-anchor" href="#team-workflows" aria-label="Permalink to &quot;Team Workflows&quot;">​</a></h3><ol><li><strong>Weekly Scans:</strong> Run full scans weekly</li><li><strong>Size Budgets:</strong> Set per-type size budgets</li><li><strong>Documentation:</strong> Keep exported CSVs in version control</li><li><strong>Reviews:</strong> Discuss large assets in team meetings</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="scan-takes-too-long" tabindex="-1">Scan Takes Too Long <a class="header-anchor" href="#scan-takes-too-long" aria-label="Permalink to &quot;Scan Takes Too Long&quot;">​</a></h3><p><strong>Cause:</strong> Very large project (100,000+ assets)</p><p><strong>Solution:</strong></p><ul><li>Scan specific folders instead</li><li>Filter by asset type first</li><li>Close unnecessary Editor windows</li></ul><h3 id="asset-not-showing" tabindex="-1">Asset Not Showing <a class="header-anchor" href="#asset-not-showing" aria-label="Permalink to &quot;Asset Not Showing&quot;">​</a></h3><p><strong>Cause:</strong> Below size threshold or filtered out</p><p><strong>Solution:</strong></p><ul><li>Reset size threshold to 0</li><li>Select &quot;All Assets&quot; in type filter</li><li>Clear search box</li></ul><h3 id="memory-size-seems-wrong" tabindex="-1">Memory Size Seems Wrong <a class="header-anchor" href="#memory-size-seems-wrong" aria-label="Permalink to &quot;Memory Size Seems Wrong&quot;">​</a></h3><p><strong>Cause:</strong> Estimated value, not exact runtime size</p><p><strong>Note:</strong> Memory sizes are estimates based on asset properties. Actual runtime memory may vary based on compression, streaming, and engine settings.</p>',73)])])}const g=a(l,[["render",o]]);export{p as __pageData,g as default};
